// The precache list is generated by npm run build; each build becomes an update.

importScripts('/sw-precache.js');
const worker = /** @type {ServiceWorkerGlobalScope} */ (/** @type {unknown} */ (self));
const STATIC = new Set(SHELL.filter(path => path !== '/'));

// Installation succeeds only after the HTML and its build assets are saved.
worker.addEventListener('install', event => {
  event.waitUntil(caches.open(CACHE).then(cache => cache.addAll(SHELL)));
});
worker.addEventListener('activate', event => {
  event.waitUntil(caches.keys().then(keys => Promise.all(keys
    .filter(key => key.startsWith('saiv-shell-') && key !== CACHE)
    .map(key => caches.delete(key)))));
});
worker.addEventListener('message', event => {
  if (event.data?.type === 'SKIP_WAITING') void worker.skipWaiting();
});
worker.addEventListener('fetch', event => {
  const request = event.request;
  const url = new URL(request.url);
  if (request.method !== 'GET' || url.origin !== worker.location.origin) return;
  // An allowlist excludes API responses, RSC payloads and biometric data.
  if (request.mode === 'navigate' && (url.pathname === '/' || url.pathname === '/attendance')) {
    event.respondWith(fetch(request).catch(async () =>
      (await (await caches.open(CACHE)).match(url.pathname)) || Response.error()));
  } else if (!url.search && STATIC.has(url.pathname)) {
    event.respondWith(caches.open(CACHE).then(async cache =>
      (await cache.match(request)) || fetch(request)));
  }
});
